                                                                                                                                                                                                             
  CREATE TABLE "CHECK_CHANGE_RECORD"                                                                                                                                                              
   (	"RECORD_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"RECORD_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                         
	"RECORD_USER_ID" NUMBER(20,0),                                                                                                                                                                              
	"RECORD_NAME" VARCHAR2(200),                                                                                                                                                                                
	"RECORD_JOB_NUMBER" VARCHAR2(200),                                                                                                                                                                          
	"REMARK" VARCHAR2(4000),                                                                                                                                                                                    
	"IMAGES" VARCHAR2(4000),                                                                                                                                                                                    
	"EFFECT_MINUTE" NUMBER(20,0),                                                                                                                                                                               
	"CONFIG_ID" NUMBER(20,0),                                                                                                                                                                                   
	"CONFIG_NAME" VARCHAR2(500),                                                                                                                                                                                
	"DEPT_ID" NUMBER,                                                                                                                                                                                           
	"DEPT_NAME" VARCHAR2(500),                                                                                                                                                                                  
	"AREA_ID" NUMBER,                                                                                                                                                                                           
	"AREA_NAME" VARCHAR2(500),                                                                                                                                                                                  
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                         
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                  
	"CREATION_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                       
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                  
	"UPDATED_DATE" DATE,                                                                                                                                                                                        
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                               
	 PRIMARY KEY ("RECORD_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                        
   ) ;                                                                                                                                                                                                       

